/* v77: independent architecture silhouettes, 30 templates x 8 colourways.
   Buildings are procedural sprite canvases; no flat illustration overlays. */
const SECT77_NAMES=['Citadel','Sky Monastery','Iron Foundry','Canopy Village','Step Pyramid','Cliff Dwellings','Crystal Spires','River Delta','Watch Fortress','Sun Basilica','Steamworks','Living Grove','Mesa Stronghold','Moon Observatory','Copper Mill','Root Sanctuary','Obsidian Keep','Desert Ziggurat','Glass Conservatory','Hanging Gardens','Castle of Blades','Star Lanterns','Volcanic Kilns','Mangrove Homes','Storm Bastion','Crescent Shrine','Mechanical Yard','Mushroom Commune','Snow Ramparts','Floating Archives'];
const SECT77_COLORS=['#9b4750','#315e9e','#4c8661','#ac833e','#855e9f','#b2b9c1','#247e89','#a96282'];
function tw7423SectSprite(type,snow,variant,style){
 style=((style|0)%30+30)%30;const shade=((variant|0)%8+8)%8;
 const key='v77/architecture/'+style+'/'+shade+'/'+type+'/'+!!snow;
 if(TW65.spr[key])return TW65.spr[key];
 const original=tw65Sprite(type,snow,shade%2),cv=document.createElement('canvas');
 cv.width=original.width;cv.height=original.height;
 const g=cv.getContext('2d');g.imageSmoothingEnabled=false;
 const W=cv.width,H=cv.height,unit=Math.max(2,Math.round(Math.min(W,H)/42));
 const px=(x)=>Math.round(x*W),py=(y)=>Math.round(y*H);
 const fill=(color,x,y,w,h)=>{g.fillStyle=color;g.fillRect(px(x),py(y),Math.max(unit,px(w)),Math.max(unit,py(h)))};
 const polygon=(color,pts)=>{g.fillStyle=color;g.beginPath();pts.forEach(([x,y],i)=>i?g.lineTo(px(x),py(y)):g.moveTo(px(x),py(y)));g.closePath();g.fill()};
 const outline='#251d26', stone=snow?'#cbd9da':'#a59b88', shadow=snow?'#728c99':'#574f50';
 const paint=SECT77_COLORS[shade],glow=shade===5?'#eff9ff':'#f5d794';
 const styleGroup=Math.floor(style/3),substyle=style%3;
 // Independent structural silhouettes: ten architecture families, three roof/vertical profiles each.
 // Buildings are assembled as crisp opaque pixels, and support eight independent palettes.
 g.clearRect(0,0,W,H);
 const baseY=.72;
 function body(x,y,w,h,material=stone){fill(outline,x-.012,y-.012,w+.024,h+.025);fill(shadow,x+.018,y+.018,w,h);fill(material,x,y,w-.027,h-.03)}
 function windows(x,y,n=3){for(let k=0;k<n;k++){let xx=x+k*.17;fill(outline,xx,y,.063,.12);fill(glow,xx+.014,y+.016,.032,.079)}}
 function roof(x,y,w,peak=.11){polygon(outline,[[x-.035,y+.033],[x+w/2,y-peak-.025],[x+w+.035,y+.033]]);polygon(paint,[[x,y],[x+w/2,y-peak],[x+w,y]]);fill(outline,x-.034,y+.022,w+.067,.026)}
 function battlement(x,y,w){fill(outline,x-.016,y,w+.032,.045);fill(stone,x,y,w,.029);for(let k=0;k<7;k++)fill(stone,x+w*(k/7),y-.065,w*.075,.07)}
 function tower(x,y,w,h){body(x,y,w,h);roof(x-.03,y+.01,w+.06,.075);fill(outline,x+w*.36,y+h*.36,w*.28,.13);fill(glow,x+w*.39,y+h*.39,w*.19,.065)}
 function pilaster(x,y,h){fill(outline,x,y,.055,h);fill(stone,x+.012,y+.01,.030,h-.02)}
 function tree(x,y,h){fill('#392e30',x,y,.095,h);for(let t=0;t<3;t++)polygon(t%2?'#36654d':'#568a59',[[x-.14,y+h*.48-t*.10],[x+.055,y-h*.20-t*.11],[x+.24,y+h*.48-t*.10]])}
 function arch(x,y,w,h){body(x,y,w,h);fill(outline,x+w*.32,y+h*.37,w*.36,h*.64);fill('#373039',x+w*.36,y+h*.44,w*.28,h*.52)}
 // Ground baseline deliberately remains at .93 for uniform placement.
 if(styleGroup===0){ // masonry fortress with distinct wall/tower configurations
   body(.10,.42,.80,.40);battlement(.10,.42,.80);for(let k=0;k<2+substyle;k++)tower(.05+k*(.77/(1+substyle)),.24+(k%2)*.10,.17,.52);arch(.37,.59,.25,.30);
 }else if(styleGroup===1){ // tall sacred/temple skyline
   body(.13,.47,.74,.40,'#d4c2a1');for(let k=0;k<3+substyle;k++)pilaster(.19+k*.18,.49,.36);roof(.07,.46,.86,.16+substyle*.04);tower(.39,.16-substyle*.035,.22,.32);windows(.25,.65,3);
 }else if(styleGroup===2){ // factory asymmetry and smokestacks
   body(.11,.48,.78,.39,'#766e67');roof(.07,.47,.52,.17);for(let k=0;k<2+substyle;k++){fill(outline,.60+k*.095,.08+(k%2)*.07,.088,.46);fill('#9c6952',.619+k*.095,.12+(k%2)*.07,.049,.39)}windows(.18,.67,3);
 }else if(styleGroup===3){ // organic connected tree dwellings
   tree(.18,.38,.50);tree(.70,.32,.54);body(.13,.41,.31,.17,'#957a54');body(.58,.35,.32,.19,'#957a54');roof(.09,.42,.39,.12);roof(.55,.35,.37,.15);fill('#533f30',.37,.56,.35,.035);if(substyle)tree(.44,.32,.41);
 }else if(styleGroup===4){ // pyramid complex
   for(let level=0;level<4+substyle;level++){let w=.82-level*.125;fill(level%2?stone:shadow,(1-w)/2,.76-level*.12,w,.13)}fill(glow,.45,.25,.10,.09);for(let k=0;k<3;k++)fill(outline,.34+k*.11,.76,.06,.12);
 }else if(styleGroup===5){ // vertical cliff-carved network with bridges
   polygon(shadow,[[.10,.87],[.13,.34],[.32,.17],[.56,.21],[.83,.08],[.91,.90]]);for(let k=0;k<3+substyle;k++){let yy=.33+k*.14;fill(stone,.23,yy,.48,.064);fill(outline,.29,yy+.015,.10,.065);fill(glow,.32,yy+.03,.042,.031)}fill('#826b51',.44,.35,.05,.46);if(substyle)roof(.18,.31,.64,.07);
 }else if(styleGroup===6){ // crystalline spires with mineral foundations
   body(.16,.63,.68,.25);for(let k=0;k<3+substyle;k++){let xx=.14+k*.17;polygon(outline,[[xx,.67],[xx-.03,.38],[xx+.075,.07+(k%2)*.18],[xx+.14,.39],[xx+.14,.67]]);polygon(paint,[[xx+.01,.63],[xx,.40],[xx+.077,.12+(k%2)*.18],[xx+.11,.47],[xx+.13,.64]])}windows(.28,.74,3);
 }else if(styleGroup===7){ // stilt, river or floating settlement, connected decking
   for(let k=0;k<4;k++)fill(outline,.13+k*.20,.58,.05,.34);fill('#957a50',.06,.62,.86,.055);body(.11,.38,.33,.24);body(.53,.30,.35,.32);roof(.07,.39,.39,.13);roof(.49,.31,.44,.17);fill('#5b8392',.04,.92,.91,.035);
 }else if(styleGroup===8){ // huge rounded dome and arched civic hall
   body(.09,.54,.82,.34,'#c5b7a5');polygon(outline,[[.11,.55],[.16,.37],[.34,.22],[.66,.22],[.85,.38],[.90,.55]]);polygon(paint,[[.15,.53],[.20,.39],[.35,.26],[.65,.26],[.81,.40],[.85,.53]]);for(let k=0;k<3+substyle;k++)pilaster(.19+k*.16,.58,.28);arch(.40,.62,.20,.27);
 }else{ // sky archive / spired modular pagodas
   body(.10,.54,.80,.34);for(let level=0;level<2+substyle;level++){let ww=.76-level*.18,x=(1-ww)/2,y=.49-level*.15;body(x,y,ww,.12);roof(x-.06,y,ww+.12,.07)}tower(.42,.06,.15,.19);windows(.26,.71,3);
 }
 // Independent detailing across each of 30 types: equipment, roofs and skyline differ.
 if(substyle===1){fill(glow,.90,.31,.04,.13);fill(outline,.895,.29,.05,.02)}
 if(substyle===2){fill(outline,.03,.56,.055,.31);fill(glow,.04,.52,.034,.07);fill(outline,.91,.48,.045,.38)}
 if(snow){g.fillStyle='#e8f3f1';g.fillRect(px(.12),py(.89),px(.76),Math.max(2,unit))}

