const TW64KEY={K:'sectcliff',O:'sectcliff',F:'sectcliff',H:'secthall',W:'sectterrace',S:'sectstair',P:'sectpath',p:'sectpath'};
/* Layout: stacked terraces. Each = 2 hall rows (non-walk plot ground) + 1 walkway (buildings are anchored here, like village doors) + 1 cliff-face row.
   A 3-tile stair column links each walkway to the one above; sides alternate (switchback). Building slots are fitted from the engine's real PLOTS sizes. */
function tw64Plan(cx,top,T,hs,rooms){
 const sectStyle=(hs>>>13)%30,sectFamily=sectStyle%4,spread=((hs>>>3)%7)-3,shape=(hs>>>10)%5;
 // FOUR distinct landforms, not four recolors of the same mountain.
 // Fortress: broad, stepped rectangular citadel; sanctuary: tiered shrine with side chapels;
 // forge: offset asymmetric foundry; ranger: split forest platforms and branch walks.
 const profiles=sectFamily===0?(T===3?[13,11,9]:[12,9]):sectFamily===1?(T===3?[12,7,10]:[11,8]):sectFamily===2?(T===3?[14,10,6]:[13,7]):(T===3?[11,7,11]:[10,9]);
 const hw=profiles.map((w,t)=>Math.max(5,w+Math.max(-2,Math.min(2,spread))+(sectFamily===2&&t===0?2:0)));
 const M=new Map(),bottom=top+4*T,side=hs&1?-1:1,stairX=[],deco=[];
 const put=(x,y,k,t)=>M.set(x+','+y,{x,y,k,t}),jag=(x,y)=>tw64N(x,y,hs)<.3,R4=t=>{const f=bottom-4*t;return[f-3,f-2,f-1,f]};
 for(let t=0;t<T;t++){const[h0,h1,w,f]=R4(t),W=hw[t];
  for(let y=h0;y<=f;y++)for(const sg of[-1,1]){put(cx+sg*(W+1),y,'K',t);if((t==0&&sg==side)||!(jag(cx+sg*(W+2),y)||(t==0&&y==f)))put(cx+sg*(W+2),y,'O',t)}
  for(let x=cx-W;x<=cx+W;x++){put(x,f,'F',t);put(x,w,'W',t);put(x,h0,'H',t);put(x,h1,'H',t)}}
 const hT=hw[T-1];for(let x=cx-hT-1;x<=cx+hT+1;x++)put(x,top,'K',T-1);
 for(const sg of[-1,1])if(!jag(cx+sg*(hT+2),top))put(cx+sg*(hT+2),top,'O',T-1);
 for(let t=0;t<T-1;t++){const[h0,h1]=R4(t),xs=cx+(((t+(hs>>1))%2)?-1:1)*(hw[t+1]-1);stairX[t]=xs;put(xs,h0,'S',t);put(xs,h1,'S',t);put(xs,R4(t+1)[3],'S',t+1)}
 put(cx,bottom,'S',0);for(let i=1;i<=3;i++)put(cx,bottom+i,'p',0);
 // Landform extensions are REAL world tiles, included in placement safety checks.
 const wings=(x,y,width,kind,t)=>{for(let dx=0;dx<width;dx++){put(x+dx,y,'W',t);put(x+dx,y+1,kind,t);}};
 if(sectFamily===0){ // fortress: bastions and a defensive gatehouse
   for(const sign of [-1,1]){const anchor=cx+sign*(hw[0]+1);
     for(let yy=bottom-4;yy<=bottom-1;yy++)for(let dx=0;dx<4;dx++)put(anchor+sign*dx,yy,dx===3?'K':yy===bottom-1?'F':'W',0);
     for(let dy=0;dy<2;dy++)put(cx+sign*(hw[T-1]+2),top+dy,'K',T-1);
   }
 }else if(sectFamily===1){ // sanctuary: paired shrine courts and an open ceremonial approach
   for(const sign of [-1,1]){const ax=cx+sign*(hw[0]+2);
     for(let yy=bottom-4;yy<=bottom-2;yy++)for(let dx=0;dx<4;dx++)put(ax+sign*dx,yy,yy===bottom-2?'F':'W',0);
     for(let dy=0;dy<3;dy++)put(cx+sign*(hw[T-1]+2),top+dy,dy===2?'F':'H',T-1);
   }
   for(let yy=bottom+1;yy<=bottom+4;yy++)put(cx,yy,'P',0);
 }else if(sectFamily===2){ // forge: single large industrial wing and a tall narrow crest
   const ax=cx+side*(hw[0]+1);
   for(let yy=bottom-5;yy<bottom;yy++)for(let dx=0;dx<7;dx++)put(ax+side*dx,yy,yy===bottom-1?'F':dx===6?'K':'W',0);
   for(let yy=top-2;yy<=top;yy++)for(let dx=-2;dx<=2;dx++)put(cx+dx,yy,yy===top?'K':'H',T-1);
 }else{ // ranger: separated lookout platforms connected by narrow walkways
   for(const sign of [-1,1]){const ax=cx+sign*(hw[0]+2);
     for(let yy=bottom-3;yy<=bottom;yy++)for(let dx=0;dx<5;dx++)put(ax+sign*dx,yy,yy===bottom?'F':dx===4?'K':'W',0);
     for(let dx=1;dx<=3;dx++)put(cx+sign*(hw[0]+dx),bottom-2,'P',0);
   }
 }
 // Thirty distinct footprint configurations, separate from the faction palette.
 // Side terraces are real, walkable tiles, not composited illustrations.
 const configuration=Math.floor(sectStyle/4),bank=configuration%3,extent=2+configuration%4;
 for(const sign of [-1,1]){
   if((configuration+sign+30)%3===0)continue;
   const edge=cx+sign*(hw[0]+2),level=bottom-2-(configuration%2);
   for(let d=0;d<extent;d++){
     put(edge+sign*d,level,'P',0);
     if(bank===0)put(edge+sign*d,level+1,'W',0);
     if(bank===1&&d===extent-1)put(edge+sign*d,level-1,'K',0);
     if(bank===2&&d%2===0)put(edge+sign*d,level+1,'F',0);
   }
 }
 // Eight architectural arrangements vary annex length, direction and elevation.
 const annexSide=(configuration%2)?-side:side;
 if(configuration>=2){
   const ay=top+1+(configuration%Math.max(1,T));
   const base=cx+annexSide*(hw[T-1]+2);
   for(let d=0;d<2+configuration%5;d++){
     put(base+annexSide*d,ay,'W',T-1);
     if(d%2===0)put(base+annexSide*d,ay-1,'H',T-1);
   }
 }
 const P={M,hw,bottom,side,sectStyle,stairX,rooms:[],deco,wf:{x0:side>0?cx+hw[0]+1:cx-hw[0]-2,y0:bottom-3}};
 if(!rooms)return P;
 const LIST=T==3?[[['house',1],['house',2],['house',3],['house',4],['blacksmith',3]],[['barracks',2],['temple',2],['range',3],['house',4],['tower',4]],[['sectHall',1],['tower',2],['sectAltar',1]]]:[[['house',1],['house',2],['barracks',2],['house',3],['temple',3],['house',4]],[['sectHall',1],['tower',2],['sectAltar',1]]];
 // Each founder has a persistent compound vocabulary, not one common blueprint.
 // Only use existing registered buildings with known plots: placement and pathfinding stay valid.
 const style=(hs>>>13)%8;
 // Structural archetypes: different *physical building lists*, floor populations and construction priorities.
 const archetype=style%4;
 const architectures=[
  {low:[['house',1],['house',2],['barracks',2],['range',3],['tower',3]],middle:[['barracks',2],['tower',2],['blacksmith',3],['range',3]],summit:[['sectHall',1],['tower',2],['tower',3],['sectAltar',1]]},
  {low:[['house',1],['house',2],['temple',2],['house',3],['range',4]],middle:[['temple',2],['house',3],['sectAltar',2],['temple',4]],summit:[['sectHall',1],['temple',2],['sectAltar',1]]},
  {low:[['blacksmith',1],['house',2],['blacksmith',3],['tower',3]],middle:[['blacksmith',2],['barracks',3],['tower',4]],summit:[['sectHall',1],['blacksmith',2],['tower',3],['sectAltar',1]]},
  {low:[['house',1],['range',2],['house',2],['range',3]],middle:[['range',2],['temple',3],['house',3]],summit:[['sectHall',1],['temple',2],['sectAltar',1]]}
 ];
 const pattern=architectures[archetype];
 for(let t=0;t<T;t++)LIST[t]=(t===0?pattern.low:t===T-1?pattern.summit:pattern.middle).map(v=>v.slice());
 const themes=[
  [['house',2],['range',3]], [['temple',2],['house',3]],
  [['blacksmith',3],['tower',3]], [['barracks',2],['range',2]],
  [['tower',2],['temple',3]], [['house',2],['blacksmith',3]],
  [['range',2],['tower',4]], [['temple',3],['barracks',3]]
 ];
 for(let t=0;t<T;t++){
  const pool=themes[(style+t*3)%themes.length];
  // Rotate which specialist facilities dominate each tier, but keep the ancestral hall.
  const ordinary=LIST[t].filter(([k])=>k!=='sectHall');
  const replaces=0;
  for(let j=0;j<replaces;j++){
   const target=ordinary.findIndex(([k])=>k==='house'||k==='tower'||k==='range');
   if(target>=0)ordinary[target]=pool[j%pool.length].slice();
  }
  LIST[t]=t===T-1?[['sectHall',1],...ordinary]:ordinary;
 }
 P.rooms.push({type:'sectGate',ax:cx,ay:bottom,lv:1,t:0});
 for(let t=0;t<T;t++){const yw=R4(t)[2];let cur=[[cx-hw[t],cx+hw[t]+1]];const cut=(c0,c1)=>{const nx=[];for(const[s0,s1]of cur){if(c1<=s0||c0>=s1){nx.push([s0,s1]);continue}if(c0>s0)nx.push([s0,c0]);if(c1<s1)nx.push([c1,s1])}cur=nx};
  if(t<T-1)cut(stairX[t]-.15,stairX[t]+1.15);if(t==0)cut(cx-1.4,cx+2.4);
  const list=LIST[t].slice().sort((a,b)=>tw64N(hs+t,a[0].length+a[1],hs)-tw64N(hs+t,b[0].length+b[1],hs));
  if(t==T-1){const w=PLOTS.sectHall[0];P.rooms.push({type:'sectHall',ax:cx,ay:yw,lv:1,t});cut(cx+.5-w/2-.55,cx+.5+w/2+.55);const hallIndex=list.findIndex(([kind])=>kind==='sectHall');if(hallIndex!==-1)list.splice(hallIndex,1)}
  /* best-fit packing of the engine's real plot widths into the free stretches of this walkway */
  const items=list.map(([type,lv])=>({type,lv,w:PLOTS[type][0]})).sort((a,b)=>a.lv-b.lv||b.w-a.w);
  for(const it of items){let best=null;for(const s of cur){const ax=Math.ceil(s[0]+it.w/2-.5),end=ax+.5+it.w/2;if(end<=s[1]+.35){const left=s[1]-end;if(!best||left<best.left)best={s,ax,end,left}}}
   if(best){P.rooms.push({type:it.type,ax:best.ax,ay:yw,lv:it.lv,t});best.s[0]=best.end+.5}}}
 for(const m of M.values())if(m.k=='K'&&tw64N(m.x,m.y,hs+5)>.82&&!(m.t==0&&Math.sign(m.x-cx)==side))deco.push({k:'tree',x:m.x+.5,y:m.y+1,s:2.1+tw64N(m.y,m.x,3)*.6,v:tw64N(m.x,m.y,9)*3|0});
 for(const sg of[-1,1])if(sg!=side)deco.push({k:'rock',x:cx+sg*(hw[0]+1)+.5,y:bottom+1,s:1.5,v:0});
 return P}
function tw64Find(s,T){
 const W=G.W,H=G.H,hs=tw64H(s.name),sx=s.x|0,sy=s.y|0,hw0=(T==3?10:8)+(((hs>>>3)%5)-2),cand=[],bl=[...G.bld].filter(([i])=>Number.isInteger(i)&&Math.abs(i%W-sx)<48&&Math.abs((i/W|0)-sy)<48).map(([i,b])=>plot(b,i%W,i/W|0)),dg=Object.values(G.state.dungeons||{});
 const free=(x,y)=>{if(x<2||y<2||x>=W-2||y>=H-2||!G.walk(x,y))return false;const k=G.terr(y*W+x).key;return k!=='coast'&&!k.startsWith('sect')};
 for(let top=sy-4*T-18;top<=sy+6;top+=2)for(let cx=sx-22;cx<=sx+22;cx+=2){
  const bot=top+4*T,rect={left:cx-hw0-2,right:cx+hw0+3,top:top-1,bottom:bot+2};
  if(!s.town&&!s.noTown&&sx>=rect.left-5&&sx<=rect.right+5&&sy>=rect.top-5&&sy<=rect.bottom+5)continue;   /* town not founded yet: leave its spot free */

