const oldBuildingRace=buildingRace;
buildingRace=function(i){const v=G.state?.buildingStyles?.[i];if(typeof v==='string'&&v.startsWith('v73:'))return v;
 for(const s of Object.values(G.state?.sects||{})){if(!s.mt)continue;if(s.mt.rooms?.some(r=>r.i===i)){const name='v73:'+s.name;G.state.buildingStyles[i]=name;return name}}
 return oldBuildingRace(i);
};
const priorArch=architectureSprite,priorDev=developedArchitecture;
function styleSprite(type,race,variant,level){if(typeof race!=='string'||!race.startsWith('v73:'))return null;
 const s=G.state?.sects?.[race.slice(4)];if(!s)return null;
 const id=identity(s);const base=tw65Sprite(type,!!s.mt?.snow,(id.seed>>>4)%2);
 return tint(base,id,type+'|'+(level||0));
}
architectureSprite=function(type,race,variant=0){return styleSprite(type,race,variant)||priorArch(type,race,variant)};
developedArchitecture=function(type,race,level,variant=0){return styleSprite(type,race,variant,level)||priorDev(type,race,level,variant)};
const oldPlace=tw65Place;
tw65Place=function(s,r){const ok=oldPlace(s,r);if(ok&&r.i!==undefined){G.state.buildingStyles[r.i]='v73:'+s.name;identity(s)}return ok};
// existing mountain buildings are migrated to faction-specific art without relocating players' buildings
function migrate(g){for(const s of Object.values(g.state?.sects||{})){identity(s);for(const r of s.mt?.rooms||[])if(r.i!==undefined&&g.bld.get(r.i)===r.type)g.state.buildingStyles[r.i]='v73:'+s.name}}
